from typing import Annotated
from fastapi import Depends, FastAPI, Response
from fastapi.testclient import TestClient

app = FastAPI()
seen = []
def modify_response(response: Response):
    seen.append(response)
    response.headers['X-Modified'] = 'yes'
    response.status_code = 201
    return response

@app.get('/annotated')
def annotated(response: Annotated[Response, Depends(modify_response)]):
    assert response is seen[-1]
    return {'ok': True}

@app.get('/default')
def default(response: Response = Depends(modify_response)):
    assert response is seen[-1]
    return {'ok': True}

@app.get('/plain')
def plain(response: Response):
    response.headers['X-Plain'] = 'yes'
    return {'ok': True}

client = TestClient(app)
for path in ('/annotated', '/default'):
    result = client.get(path)
    assert result.status_code == 201
    assert result.headers['X-Modified'] == 'yes'
    assert result.json() == {'ok': True}
assert len(seen) == 2
assert client.get('/plain').headers['X-Plain'] == 'yes'
assert client.get('/openapi.json').status_code == 200
print('Dependency forms and plain Response injection passed')
